package com.turboio.addon;

import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.util.zip.*;

/** Streaming derived export. Sealed raw journals stay untouched. Audio, original
 * text and identities never leave the phone unless its user selects a destination. */
final class LifelogAudioExport {
 interface Decoder extends AutoCloseable {void validate(byte[] packet,int samples48)throws IOException;void close()throws IOException;}
 interface Decoders {Decoder open()throws IOException;}
 static final long MAX_BYTES=536870912,TTL=3600000;
 static final class Draft {final String id,account,title,sha;final long size,frames,samples,parts,created;final File file;Draft(File directory,Map<String,Object> data)throws IOException{id=directory.getName();account=(String)data.get("account");title=(String)data.get("title");sha=(String)data.get("sha256");size=LifelogAudioLibrary.number(data,"bytes");frames=LifelogAudioLibrary.number(data,"frames");samples=LifelogAudioLibrary.number(data,"samples48");parts=LifelogAudioLibrary.number(data,"parts");created=LifelogAudioLibrary.number(data,"created_at");file=new File(directory,"audio.zip");require(account!=null&&account.matches("[a-f0-9]{64}")&&sha!=null&&sha.matches("[a-f0-9]{64}")&&"智记原音片段.zip".equals(title)&&size>0&&size<=MAX_BYTES&&frames>0&&parts>0,"AUDIO_EXPORT_DRAFT");}}
 private static void require(boolean value,String code)throws IOException{LifelogAudioLibrary.require(value,code);}
 private static File base(File cache)throws IOException{File root=cache.getCanonicalFile();File base=new File(root,"lifelog-audio-exports");require(root.isDirectory()&&!Files.isSymbolicLink(cache.toPath()),"AUDIO_EXPORT_PATH");if(!base.exists())require(base.mkdir(),"AUDIO_EXPORT_DIRECTORY");safe(base);return base;}
 private static void safe(File path)throws IOException{require(!Files.isSymbolicLink(path.toPath())&&path.getAbsoluteFile().equals(path.getCanonicalFile()),"AUDIO_EXPORT_PATH");}
 static String sha(File file)throws IOException{try{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)digest.update(b,0,n);}StringBuilder out=new StringBuilder();for(byte b:digest.digest())out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}catch(NoSuchAlgorithmException impossible){throw new AssertionError(impossible);}}
 static Draft prepare(File files,File cache,String account,String material,List<Object> sessions,List<Object> archives,Decoders decoders,LifelogAudioArchive.Guard guard,long now)throws IOException{
  guard.check();require(account!=null&&account.matches("[a-f0-9]{64}")&&material!=null&&material.matches("rayneo-lifelog-[a-f0-9]{64}")&&sessions.size()<=256&&archives.size()<=256,"AUDIO_EXPORT_CONTEXT");Map<String,Map<String,Object>> selected=new HashMap<>();for(Object raw:sessions){Map<String,Object> row=WireJson.map(raw);if(material.equals(row.get("material_id"))&&Boolean.TRUE.equals(row.get("source_link_verified"))&&"opus".equals(row.get("format")))selected.put((String)row.get("clock_epoch"),row);}require(!selected.isEmpty(),"AUDIO_EXPORT_SOURCE_PENDING");
  File base=base(cache);File[] prior=base.listFiles();require(prior!=null,"AUDIO_EXPORT_PATH");for(File item:prior){safe(item);require(item.getName().matches("[a-f0-9]{32}")&&item.isDirectory(),"AUDIO_EXPORT_PATH");if(now-item.lastModified()>TTL)remove(cache,item.getName());}prior=base.listFiles();require(prior!=null&&prior.length<2,"AUDIO_EXPORT_BUSY");
  String id=UUID.randomUUID().toString().replace("-","");File directory=new File(base,id);require(directory.mkdir(),"AUDIO_EXPORT_DIRECTORY");File target=new File(directory,"audio.zip");long[] totals={0,0,0,0,Long.MAX_VALUE,0};List<Object> manifest=new ArrayList<>();boolean success=false;
  try{try(FileOutputStream disk=new FileOutputStream(target);BufferedOutputStream buffer=new BufferedOutputStream(disk,65536);ZipOutputStream zip=new ZipOutputStream(buffer,StandardCharsets.UTF_8)){
   zip.setLevel(0);Set<String> seen=new HashSet<>();for(Object raw:archives){Map<String,Object> archive=WireJson.map(raw),context=WireJson.map(archive.get("context"));if(!account.equals(context.get("account")))continue;Map<String,Object> session=selected.get(context.get("clock_epoch"));if(session==null||!"sealed".equals(archive.get("phase"))||LifelogAudioLibrary.number(archive,"count")==0)continue;
    String stream=(String)archive.get("stream"),peer=(String)context.get("peer");long generation=LifelogAudioLibrary.number(context,"generation");require(stream!=null&&stream.matches("[a-f0-9]{32}")&&seen.add(stream)&&Objects.equals(peer,session.get("peer"))&&generation==LifelogAudioLibrary.number(session,"generation"),"AUDIO_EXPORT_PROVENANCE");guard.check();safe(new File(files.getCanonicalFile(),"lifelog-audio/"+account+"/"+stream));
    final OpusFile[] mux={null};final Decoder[] decoder={null};long[] count={0,0};String name=String.format(Locale.ROOT,"片段-%03d.opus",totals[2]+1);try(LifelogAudioArchive source=new LifelogAudioArchive(files,account,peer,generation,stream,guard)){
     source.visit(batch->{guard.check();require(context.get("clock_epoch").equals(batch.metadata.get("clock_epoch")),"AUDIO_EXPORT_PROVENANCE");if(!"A3".equals(batch.metadata.get("kind"))){totals[3]++;return;}AlwaysOnWire wire;AlwaysOnAudioBatch parsed;try{wire=AlwaysOnWire.read(batch.payload());require(wire.type==0xa3&&wire.message.equals(batch.metadata.get("message")),"AUDIO_EXPORT_PROVENANCE");parsed=AlwaysOnAudioBatch.parse(wire.message,wire.data());require(parsed.taskId!=null&&session.get("task_sha256").equals(LifelogAudioLibrary.hash(parsed.taskId))&&material.equals(LifelogAudioLibrary.material(account,parsed.taskId)),"AUDIO_EXPORT_PROVENANCE");require(!parsed.clamped&&parsed.unparsedBytes==0&&!parsed.frames.isEmpty(),"AUDIO_EXPORT_BATCH_UNSUPPORTED");}catch(IllegalArgumentException invalid){throw new IOException("AUDIO_EXPORT_BATCH_UNSUPPORTED");}
      for(AlwaysOnAudioBatch.Frame frame:parsed.frames){byte[] packet=frame.bytes();int samples=OpusFile.samples48(packet);if(decoder[0]==null)decoder[0]=decoders.open();decoder[0].validate(packet,samples);if(mux[0]==null){zip.putNextEntry(new ZipEntry(name));mux[0]=new OpusFile(zip,(int)Long.parseLong(stream.substring(0,8),16));}require(totals[0]<5000000&&target.length()<MAX_BYTES-65536&&directory.getUsableSpace()>67108864,"AUDIO_EXPORT_BUDGET");mux[0].packet(packet);Arrays.fill(packet,(byte)0);count[0]++;count[1]+=samples;totals[0]++;totals[1]+=samples;}
      long at=LifelogAudioLibrary.number(batch.metadata,"received_at");totals[4]=Math.min(totals[4],at);totals[5]=Math.max(totals[5],at);
     },guard);
     if(mux[0]!=null){mux[0].finish();zip.closeEntry();totals[2]++;manifest.add(WireJson.object("file",name,"frames",count[0],"samples48",count[1],"recording_complete",false));}
    }finally{if(decoder[0]!=null)decoder[0].close();}
   }
   require(totals[0]>0,"AUDIO_EXPORT_NO_FRAMES");String note="智记原音片段\n\n只包含手机已经收到并成功保存的音频；可能从智记中途开始。\n每个文件是独立保存的片段，按接收顺序导出。断连或未收到的部分不会补成静音，也不代表完整全天录音。\n未解析的非 A3 批次："+totals[3]+"。原始数据继续保留在 App。\n音频没有上传到服务器；远程保留三天尚未接入。\n";
   zip.putNextEntry(new ZipEntry("说明.txt"));zip.write(note.getBytes(StandardCharsets.UTF_8));zip.closeEntry();zip.putNextEntry(new ZipEntry("片段索引.json"));zip.write(WireJson.bytes(WireJson.object("schema",1,"parts",manifest,"first_received_at",totals[4],"last_received_at",totals[5],"source_link_verified",true,"recording_complete",false,"remote_stored",false)));zip.closeEntry();zip.finish();zip.flush();buffer.flush();disk.getFD().sync();
  }
  guard.check();require(target.length()>0&&target.length()<=MAX_BYTES,"AUDIO_EXPORT_BUDGET");Map<String,Object> receipt=WireJson.object("schema",1,"account",account,"title","智记原音片段.zip","sha256",sha(target),"bytes",target.length(),"frames",totals[0],"samples48",totals[1],"parts",totals[2],"created_at",now);try(AtomicDocument state=new AtomicDocument(new File(directory,"draft.json"),8192)){state.save(receipt);}Draft draft=new Draft(directory,receipt);guard.check();success=true;return draft;
  }finally{if(!success)remove(cache,id);}
 }
 static Draft load(File cache,String id,String account,long now)throws IOException{require(id!=null&&id.matches("[a-f0-9]{32}"),"AUDIO_EXPORT_DRAFT");File directory=new File(base(cache),id);safe(directory);File state=new File(directory,"draft.json");safe(state);require(state.isFile()&&state.length()<=8192,"AUDIO_EXPORT_DRAFT");Draft draft=new Draft(directory,WireJson.map(WireJson.read(Files.readAllBytes(state.toPath()))));safe(draft.file);require(account.equals(draft.account)&&now>=draft.created&&now-draft.created<=TTL&&draft.file.isFile()&&draft.file.length()==draft.size,"AUDIO_EXPORT_DRAFT");return draft;}
 static void copy(Draft draft,OutputStream out,LifelogAudioArchive.Guard guard)throws IOException{guard.check();safe(draft.file);require(draft.file.length()==draft.size&&draft.sha.equals(sha(draft.file)),"AUDIO_EXPORT_CHANGED");try(InputStream in=new FileInputStream(draft.file)){byte[] b=new byte[65536];int n;long total=0;while((n=in.read(b))!=-1){guard.check();total+=n;require(total<=draft.size,"AUDIO_EXPORT_CHANGED");out.write(b,0,n);}require(total==draft.size,"AUDIO_EXPORT_CHANGED");}out.flush();guard.check();}
 static void remove(File cache,String id)throws IOException{require(id!=null&&id.matches("[a-f0-9]{32}"),"AUDIO_EXPORT_DRAFT");File directory=new File(base(cache),id);safe(directory);if(!directory.exists())return;File[] list=directory.listFiles();require(list!=null&&list.length<=4,"AUDIO_EXPORT_PATH");for(File file:list){safe(file);require(Arrays.asList("audio.zip","draft.json","draft.json.partial","draft.json.lock").contains(file.getName())&&file.isFile(),"AUDIO_EXPORT_PATH");}for(File file:list)Files.delete(file.toPath());Files.delete(directory.toPath());}
}
